import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    matrix = []
    index = 1

    for i in range(n):
        row = list(map(int, data[index:index + n]))
        matrix.append(row)
        index += n

    paths = []

    def dfs(row, col, path):
        if row == n - 1 and col == n - 1:
            paths.append(path)
            return

        if row + 1 < n and matrix[row + 1][col] == 1:
            dfs(row + 1, col, path + 'D')

        if col + 1 < n and matrix[row][col + 1] == 1:
            dfs(row, col + 1, path + 'R')

    if n > 0 and matrix[0][0] == 1:
        if n == 1:
            paths.append('')
        else:
            dfs(0, 0, '')

    for path in paths:
        print(path)

if __name__ == "__main__":
    main()
